+    expect(runs).toBe(0);
+    expect(box.value).toBe(1);
+    expect(box.value).toBe(1);
+    expect(runs).toBe(1);
+  });
+
+  test(`${name} memoizes an undefined result`, () => {
+    let runs = 0;
+    const box = make(() => {
+      runs++;
+      return undefined;
+    });
+    expect(box.value).toBeUndefined();
+    expect(box.value).toBeUndefined();
+    expect(runs).toBe(1);
+  });
+
+  test(`${name} retries after the getter throws`, () => {
+    let attempts = 0;
+    const box = make(() => {
+      if (++attempts < 2) throw new Error("boom");
+      return "recovered";
+    });
